    // One row of Google's CityHash reference vectors, trimmed to the portable (non-SSE4.2-CRC) columns.
    // Each row is the set of expected hashes of data[offset .. offset+len) for the schedule in the .cpp.
    struct CityReferenceVector final
    {
        u64 m_city64;         // CityHash64
        u64 m_city64Seed;     // CityHash64WithSeed(kSeed0)
        u64 m_city64Seeds;    // CityHash64WithSeeds(kSeed0, kSeed1)
        u64 m_city128Low;     // CityHash128 low 64 bits
        u64 m_city128High;    // CityHash128 high 64 bits
        u64 m_city128SeedLow; // CityHash128WithSeed(kSeed128) low 64 bits
        u64 m_city128SeedHigh; // CityHash128WithSeed(kSeed128) high 64 bits
        u32 m_city32;         // CityHash32
    };

